CREATE TABLE account (id BIGINT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, active_device VARCHAR(100) NOT NULL DEFAULT '', epoch BIGINT NOT NULL DEFAULT 0);
CREATE TABLE login_session (token_hash CHAR(64) PRIMARY KEY, account_id BIGINT NOT NULL, device_id VARCHAR(100) NOT NULL, epoch BIGINT NOT NULL, expires_at TIMESTAMP NOT NULL, revoked BOOLEAN NOT NULL DEFAULT FALSE, FOREIGN KEY(account_id) REFERENCES account(id), INDEX(account_id));
CREATE TABLE service_credential (id VARCHAR(80) PRIMARY KEY, token_hash CHAR(64) NOT NULL UNIQUE, scopes VARCHAR(120) NOT NULL, revoked BOOLEAN NOT NULL DEFAULT FALSE, expires_at TIMESTAMP NULL);
CREATE TABLE theme (id VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, current_version VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NULL, listed BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE entitlement (account_id BIGINT NOT NULL, theme_id VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, allowed BOOLEAN NOT NULL DEFAULT TRUE, PRIMARY KEY(account_id,theme_id), FOREIGN KEY(account_id) REFERENCES account(id), FOREIGN KEY(theme_id) REFERENCES theme(id));
CREATE TABLE theme_version (theme_id VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, version VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, state VARCHAR(20) NOT NULL DEFAULT 'draft', revision BIGINT NOT NULL DEFAULT 1, validated_revision BIGINT NULL, scene_json JSON NOT NULL, manifest_json JSON NOT NULL, license_json JSON NOT NULL, validation_json JSON NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, published_at TIMESTAMP NULL, PRIMARY KEY(theme_id,version), FOREIGN KEY(theme_id) REFERENCES theme(id));
CREATE TABLE media_file (sha256 CHAR(64) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, bytes BIGINT NOT NULL, kind VARCHAR(10) NOT NULL, codec VARCHAR(40) NOT NULL, container VARCHAR(20) NOT NULL, channels INT NOT NULL, sample_rate INT NOT NULL, duration DOUBLE NOT NULL, mime VARCHAR(80) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE catalog_clock (id INT PRIMARY KEY, revision BIGINT NOT NULL);
INSERT INTO catalog_clock VALUES(1,0);
CREATE TABLE catalog_event (revision BIGINT PRIMARY KEY, theme_id VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, account_id BIGINT NULL);
CREATE TABLE audit_log (id BIGINT PRIMARY KEY AUTO_INCREMENT, actor VARCHAR(80) NOT NULL, action VARCHAR(40) NOT NULL, target VARCHAR(200) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
